{"modifiedFiles":[],"workingNote":"既存の protocol_adapter、WorldState、Fen/Zef のルールを確認し、新しい操作の公開名と原子性を既存契約に合わせて追加します。"}{"modifiedFiles":[],"workingNote":"lockFenZef は Fen/Zef がともに pex の場合だけ、1回の状態遷移で両方を dor にする方針です。既存操作のエラー形式とスナップショット形式を確認中です。"}{"modifiedFiles":[{"path":"src/protocol_adapter.ts","content":"// protocol_adapter.ts
//
// これは「文化的に継承されるartifact」ではなく、実験世界の固定された
// 外部境界条件である（schema.ts の WorldProtocol コメント参照）。
// H(G) は internal な rules.ts / entity module 構造を一切知らず、
// このファイルがexportする関数だけを呼ぶ。
//
// worker AIは、内部構造（vok/zef/tal/fen/osk ディレクトリ、rules.ts の分割方法等）を
// 自由にリファクタしてよいが、この protocol_adapter.ts が定義する
// エクスポート名・振る舞いだけは保持しなければならない
// （Generation 0で確定した固定契約）。

import { WorldProtocol, OperationResult } from "../../schema";
import { WorldState, createInitialWorld } from "./world";
import { advanceVok1, advanceVok2 } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";
import { advanceTal1 } from "./tal/rules";
import { advanceOsk1 } from "./osk/rules";
import { advanceFen1, advanceFen2 } from "./fen/rules";

/**
 * Fen と Zef を、それぞれの通常操作の中間状態を返さずに同時に dor へ進める。
 * 各エンティティの既存の前提条件も維持する。
 */
function lockFenZef(world: WorldState): WorldState {
  if (world.fen !== "pex") {
    throw new Error("lockFenZef: Fen must be in state 'pex'");
  }
  if (world.zef !== "pex") {
    throw new Error("lockFenZef: Zef must be in state 'pex'");
  }
  if (world.osk !== "pex") {
    throw new Error("lockFenZef: requires Osk to be 'pex'");
  }
  if (world.tal !== "pex") {
    throw new Error("lockFenZef: requires Tal to be 'pex'");
  }

  return { ...world, fen: "dor", zef: "dor" };
}

// displayName -> 内部操作の対応表。この対応表自体は世代を経て
// リファクタされてよい（新operationの追加や、内部関数の再編を含む）。
// ただし各displayNameのキー文字列（"advanceVok1"等）はcontractの一部として固定。
const operationTable: Record<string, (w: WorldState) => WorldState> = {
  advanceVok1,
  advanceVok2,
  advanceZef1,
  advanceZef2,
  advanceTal1,
  advanceOsk1,
  advanceFen1,
  advanceFen2,
  lockFenZef,
};

// entity display name -> WorldStateのプロパティ名
const entityFieldTable: Record<string, keyof WorldState> = {
  Vok: "vok",
  Zef: "zef",
  Tal: "tal",
  Fen: "fen",
  Osk: "osk",
};

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string,
  ): OperationResult {
    const operation = operationTable[operationDisplayName];
    if (!operation) {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    try {
      return { success: true, newState: operation(state) };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : String(error),
      };
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    const field = entityFieldTable[entityDisplayName];
    if (!field) {
      throw new Error(`Unknown entity: ${entityDisplayName}`);
    }
    return state[field];
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return {
      Vok: state.vok,
      Zef: state.zef,
      Tal: state.tal,
      Fen: state.fen,
      Osk: state.osk,
    };
  },
};
"}],"workingNote":"protocol_adapter に lockFenZef を追加し、Fen/Zef がともに pex、既存依存の Osk/Tal も pex の場合だけ、単一のオブジェクト更新で両方を dor に遷移させます。既存の公開メソッドとエラー処理は維持しています。"}

